1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.apache.commons.codec.digest.DigestUtils;
4	
5	/**
6	 * Computes the SHA-256 hex digest of a string: its UTF-8 bytes hashed with SHA-256 and
7	 * rendered as 64 lower-case hex characters. Several owner derivations key off a stable
8	 * hash of some composed string (the {@code householdId} is the leading 12 characters of
9	 * such a digest, see {@link AssignHousehold}); centralising the digest here keeps that one
10	 * primitive in one place. It delegates to Apache Commons Codec's {@link DigestUtils} rather
11	 * than re-implementing the {@link java.security.MessageDigest} boilerplate.
12	 *
13	 * <p>A plain utility (not an OfficeFloor function), so it may expose helpers without
14	 * tripping the one-public-method-per-function rule.
15	 */
16	public final class Sha256 {
17	
18	    private Sha256() {
19	    }
20	
21	    /**
22	     * @param input the string to hash; its UTF-8 bytes are digested.
23	     * @return the SHA-256 digest as 64 lower-case hex characters.
24	     */
25	    public static String hex(String input) {
26	        return DigestUtils.sha256Hex(input);
27	    }
28	}
