1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Objects;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	
11	/**
12	 * Flags a create-owner request as a <em>possible</em> (soft) duplicate: one that is not a hard
13	 * duplicate (see {@link RejectDuplicateIdentity}) yet shares an existing owner's
14	 * {@code lastName} (compared case-insensitively with surrounding whitespace trimmed) and
15	 * {@code postcode} while carrying a <em>different</em> telephone (compared in E.164 form, see
16	 * {@link E164Telephone}). Such an owner is still created; it is merely marked so callers can
17	 * review it. When a match is found the owner's {@code possibleDuplicate} is set true and
18	 * {@code possibleDuplicateOf} to the matching owner's id (the earliest such owner by id when
19	 * several match); otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf}
20	 * is left unset.
21	 *
22	 * <p>A create that opts in with {@code sharesHousehold} is a <em>declared</em> household member,
23	 * not a suspected one, so it is never flagged: {@code possibleDuplicate} stays false.
24	 *
25	 * <p>Runs after {@link RejectDuplicateIdentity} (so a hard duplicate has already been rejected)
26	 * and within the create transaction, but before {@link SaveOwner}, so the new owner is not yet
27	 * persisted and cannot match itself.
28	 */
29	public class AssignPossibleDuplicate {
30	
31	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
32	        owner.setPossibleDuplicate(false);
33	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
34	            return; // a declared household member is not a suspected duplicate
35	        }
36	        if (normalize(owner.getPostcode()).isEmpty()) {
37	            return; // no postcode to share on
38	        }
39	        Integer matchId = earliestSoftMatch(owner, ownerRepository);
40	        if (matchId != null) {
41	            owner.setPossibleDuplicate(true);
42	            owner.setPossibleDuplicateOf(matchId);
43	        }
44	    }
45	
46	    /**
47	     * The id of the earliest existing owner (lowest id) that {@code owner} is a soft duplicate of,
48	     * or {@code null} when none matches.
49	     */
50	    private static Integer earliestSoftMatch(Owner owner, OwnerRepository ownerRepository) {
51	        Integer matchId = null;
52	        for (Owner existing : ownerRepository.findAll()) {
53	            if (!isSoftMatch(owner, existing)) {
54	                continue;
55	            }
56	            if (matchId == null || existing.getId() < matchId) {
57	                matchId = existing.getId();
58	            }
59	        }
60	        return matchId;
61	    }
62	
63	    /**
64	     * Whether {@code existing} makes {@code owner} a soft (possible) duplicate: a different,
65	     * live owner sharing its last name and postcode but carrying a different telephone (the same
66	     * telephone would be a hard duplicate, already rejected upstream).
67	     */
68	    private static boolean isSoftMatch(Owner owner, Owner existing) {
69	        if (owner.getId() != null && owner.getId().equals(existing.getId())) {
70	            return false;
71	        }
72	        if (existing.isDeleted()) {
73	            return false; // a soft-deleted owner is not a possible duplicate
74	        }
75	        if (!normalize(existing.getLastName()).equals(normalize(owner.getLastName()))) {
76	            return false;
77	        }
78	        if (!normalize(existing.getPostcode()).equals(normalize(owner.getPostcode()))) {
79	            return false;
80	        }
81	        String telephone = E164Telephone.normalizeOrNull(owner.getTelephone());
82	        String existingTelephone = E164Telephone.normalizeOrNull(existing.getTelephone());
83	        // same telephone is not a soft match (it would be a hard duplicate)
84	        return !Objects.equals(telephone, existingTelephone);
85	    }
86	
87	    private static String normalize(String value) {
88	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
89	    }
90	}
