1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Rejects a create-owner request whose {@link OwnerIdentity#key(Owner) identity key} already
11	 * belongs to an existing owner. The key consolidates all duplicate detection — it is
12	 * {@code normalizedTelephone + '|' + email + '|' + householdId} — so a new owner collides only
13	 * when its telephone, email <em>and</em> household all match an existing owner's. Because the
14	 * telephone is part of the key, two members of the same household (same {@code householdId},
15	 * derived deterministically from last name and postcode, see {@link AssignHousehold}) with
16	 * different telephones have different keys and are both allowed; the later
17	 * {@link AssignPossibleDuplicate} step merely flags the second as a soft duplicate.
18	 *
19	 * <p>{@code sharesHousehold} bypasses this block outright: the caller is declaring the owner a
20	 * genuine additional member of that household, so the create is allowed regardless.
21	 *
22	 * <p>Runs after {@link AssignHousehold} (so the new owner's {@code householdId}, and hence its
23	 * identity key, is set) and within the create transaction, but before {@link SaveOwner}, so the
24	 * new owner is not yet persisted and cannot collide with itself.
25	 */
26	public class RejectDuplicateIdentity {
27	
28	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository)
29	            throws DuplicateIdentityException {
30	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
31	            return; // declared household member — bypass the duplicate block
32	        }
33	        String key = OwnerIdentity.key(owner);
34	        for (Owner existing : ownerRepository.findAll()) {
35	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
36	                continue;
37	            }
38	            if (existing.isDeleted()) {
39	                continue; // a soft-deleted owner does not block a new identity
40	            }
41	            if (key.equals(OwnerIdentity.key(existing))) {
42	                throw new DuplicateIdentityException(
43	                        "Another owner with the same identity already exists");
44	            }
45	        }
46	    }
47	}
