1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	/**
9	 * Assigns the owner's deterministic {@code householdId}: the first 12 hex characters of
10	 * {@code SHA-256(normalizedLastName + '|' + postcode)}. Because it is derived purely from
11	 * the (last name, postcode) pair, any two owners sharing a last name (compared
12	 * case-insensitively with runs of whitespace collapsed to a single space) and postcode
13	 * receive the <em>same</em> identifier automatically — they are, by definition, the same
14	 * household — and no owner ever has to look up or backfill another. The value never changes
15	 * as more members join.
16	 *
17	 * <p>Runs after {@link BuildOwner} (so the Owner exists) and within the create transaction,
18	 * unconditionally: {@code sharesHousehold} no longer creates the link (the link is implicit
19	 * in the identifier); it only bypasses the later household-duplicate block (see
20	 * {@link RejectDuplicateIdentity}).
21	 */
22	public class AssignHousehold {
23	
24	    public void service(@Val Owner owner) {
25	        String lastName = normalize(owner.getLastName());
26	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode().trim();
27	        owner.setHouseholdId(householdId(lastName, postcode));
28	    }
29	
30	    private static String householdId(String lastName, String postcode) {
31	        return Sha256.hex(lastName + "|" + postcode).substring(0, 12);
32	    }
33	
34	    private static String normalize(String value) {
35	        if (value == null) {
36	            return "";
37	        }
38	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
39	    }
40	}
