1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
6	
7	/**
8	 * Normalizes the create-owner telephone into E.164 form (see {@link E164Telephone}): a
9	 * leading '+' and country code are kept when present, otherwise country code '+61' is
10	 * assumed and a single leading '0' is dropped from the national digits; spaces, dashes and
11	 * brackets are stripped and the result must carry 8 to 15 digits after the '+'. Runs after
12	 * {@link RequireOwnerFields} (so the field is present) and before {@link BuildOwner},
13	 * mutating the published body in place so the mapped
14	 * {@link org.springframework.samples.petclinic.model.Owner} — and the response — carries
15	 * the E.164 value. A telephone that cannot form valid E.164 is rejected 400 via
16	 * {@link InvalidTelephoneException}.
17	 */
18	public class NormalizeOwnerTelephone {
19	
20	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
21	        request.setTelephone(E164Telephone.normalize(request.getTelephone()));
22	    }
23	}
