112	     */
113	    default String toIdentityKey(Owner owner) {
114	        return org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.key(owner);
115	    }
116	
117	    /**
118	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email is present,
119	     * otherwise {@code PHONE}.
120	     */
121	    default String toContactPreference(Owner owner) {
122	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
123	        return hasEmail ? "EMAIL" : "PHONE";
124	    }
125	
126	    /**
127	     * Derives the owner's locality (region) from its region-and-hash identity: the
128	     * {@code customerCode} is {@code <REGION>-<HASH8>}, so the locality is the REGION segment
129	     * preceding the hash. Falls back to deriving the region directly from the postcode/city
130	     * (see {@link org.springframework.samples.petclinic.rest.function.owner.OwnerCustomerCode})
131	     * only for unmigrated owners that carry no customer code.
132	     */
133	    default String toLocality(Owner owner) {
134	        String customerCode = owner.getCustomerCode();
135	        if (customerCode != null) {
136	            int dash = customerCode.indexOf('-');
137	            if (dash > 0) {
138	                return customerCode.substring(0, dash);
139	            }
140	        }
141	        return org.springframework.samples.petclinic.rest.function.owner.OwnerCustomerCode
142	                .region(owner.getPostcode(), owner.getCity());
143	    }
144	
145	    /** Region -> IANA timezone, the pinned region-to-timezone table. */
146	    java.util.Map<String, String> REGION_TIMEZONE = java.util.Map.of(
147	            "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
148	
149	    /**
150	     * Derives the owner's {@code timezone}: the IANA name for the owner's locality/region via
151	     * the fixed region-to-timezone table (NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne,
152	     * QLD-&gt;Australia/Brisbane). Returns null when the region yields no known timezone (e.g.
153	     * an {@code UNKNOWN} locality).
154	     */
155	    default String toTimezone(Owner owner) {
156	        return REGION_TIMEZONE.get(toLocality(owner));
157	    }
158	
159	    /**
160	     * Derives the owner's membership points: start at 0; add 2 when an email is present; add 1
161	     * when the owner has no namesakes ({@code namesakeCount} is 0); add 2 for a household of 3 or
162	     * more ({@code householdSize} at least 3); add 3 for tenure of at least one elapsed fiscal
163	     * year (the {@code registrationDate}'s fiscal year is earlier than the current fiscal year,
164	     * fiscal years starting 1 July). A newly created owner has zero tenure.
165	     */
166	    default Integer toMembershipPoints(Owner owner) {
167	        int points = 0;
168	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
169	        if (hasEmail) {
170	            points += 2;
171	        }
172	        boolean unique = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
173	        if (unique) {
174	            points += 1;
175	        }
176	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
177	            points += 2;
178	        }
179	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
180	        if (registrationDate != null && org.springframework.samples.petclinic.rest.function.owner.FiscalYear
181	                .elapsed(registrationDate, java.time.LocalDate.now()) >= 1) {
182	            points += 3;
183	        }
184	        return points;
185	    }
186	
187	    /**
188	     * The owner's numeric membership level (1 to 4). When a level has been stored on the owner
189	     * (the household-capped value assigned at create time, see
190	     * {@link org.springframework.samples.petclinic.rest.function.owner.AssignMembershipLevel}) it
191	     * is returned as-is; otherwise it is derived from {@code membershipPoints} (see
192	     * {@link #deriveMembershipLevel(Owner)}).
193	     */
194	    default Integer toMembershipLevel(Owner owner) {
195	        if (owner.getMembershipLevel() != null) {
196	            return owner.getMembershipLevel();
197	        }
198	        return deriveMembershipLevel(owner);
199	    }
200	
201	    /**
202	     * Derives the owner's numeric membership level (1 to 4) from its {@code membershipPoints},
203	     * before any household cap: level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, 4 for 6 or more.
204	     */
205	    default Integer deriveMembershipLevel(Owner owner) {
206	        int points = toMembershipPoints(owner);
207	        if (points >= 6) {
208	            return 4;
209	        }
210	        if (points >= 4) {
211	            return 3;
212	        }
213	        if (points >= 2) {
214	            return 2;
215	        }
216	        return 1;
217	    }
218	
219	    /**
220	     * Derives the owner's membership number as {@code <customerCode>-M<YY>}, where YY is the
221	     * last two digits of the fiscal year of the registration date (fiscal years starting 1 July;
222	     * e.g. {@code NSW-1A2B3C4D-M26}). Returns null when either the customer code or registration
223	     * date is absent (e.g. unmigrated seed data).
224	     */
225	    default String toMembershipNumber(Owner owner) {
226	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
227	            return null;
228	        }
229	        int fiscalYear = org.springframework.samples.petclinic.rest.function.owner.FiscalYear
230	                .of(owner.getRegistrationDate());
231	        return owner.getCustomerCode() + "-M" + String.format("%02d", fiscalYear % 100);
232	    }
233	
234	    /**
235	     * Derives the owner's {@code checkDigit}: the Luhn check digit (0-9) computed over the
236	     * digits contained in the {@code customerCode}. Returns null when the customer code is
237	     * absent (e.g. unmigrated seed data).
238	     */
239	    default Integer toCheckDigit(Owner owner) {
240	        String customerCode = owner.getCustomerCode();
241	        if (customerCode == null) {
242	            return null;
243	        }
244	        int sum = 0;
245	        boolean dbl = true;
246	        for (int i = customerCode.length() - 1; i >= 0; i--) {
247	            char c = customerCode.charAt(i);
248	            if (c < '0' || c > '9') {
249	                continue;
250	            }
251	            int d = c - '0';
252	            if (dbl) {
253	                d *= 2;
254	                if (d > 9) {
255	                    d -= 9;
256	                }
257	            }
258	            sum += d;
259	            dbl = !dbl;
260	        }
261	        return (10 - (sum % 10)) % 10;
262	    }
263	
264	    Owner toOwner(OwnerDto ownerDto);
265	
266	    @Mapping(target = "id", ignore = true)
267	    @Mapping(target = "pets", ignore = true)
268	    @Mapping(target = "customerCode", ignore = true)
269	    @Mapping(target = "householdId", ignore = true)
270	    @Mapping(target = "namesakeCount", ignore = true)
271	    @Mapping(target = "householdSize", ignore = true)
272	    @Mapping(target = "possibleDuplicate", ignore = true)
273	    @Mapping(target = "possibleDuplicateOf", ignore = true)
274	    @Mapping(target = "deleted", ignore = true)
275	    Owner toOwner(OwnerFieldsDto ownerDto);
276	
277	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
278	
279	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
280	
281	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
282	        OwnerPageDto ownerPageDto = new OwnerPageDto();
283	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
284	        ownerPageDto.setPage(ownerPage.getNumber());
285	        ownerPageDto.setSize(ownerPage.getSize());
286	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
287	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
288	        return ownerPageDto;
289	    }
290	}
